import{_ as i,C as r,o,c as d,a2 as a,j as t,G as n}from"./chunks/framework.BgSoyxN5.js";const b=JSON.parse('{"title":"Fear & Greed: направление, а не только уровень | TickerForge","description":"Число настроений само по себе двусмысленно: 30 на пути вверх и 30 на пути вниз — противоположные ситуации. TickerForge публикует направление, в котором движутся настроения, и отмечает дни разворота.","frontmatter":{"title":"Fear & Greed: направление, а не только уровень | TickerForge","description":"Число настроений само по себе двусмысленно: 30 на пути вверх и 30 на пути вниз — противоположные ситуации. TickerForge публикует направление, в котором движутся настроения, и отмечает дни разворота.","aside":false,"locale":"ru","alternateLocales":{"en":"/market-intelligence/fear-and-greed","ru":"/ru/market-intelligence/fear-and-greed"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/market-intelligence/fear-and-greed.md","filePath":"ru/market-intelligence/fear-and-greed.md","lastUpdated":1788410450000}'),c={name:"ru/market-intelligence/fear-and-greed.md"},p={class:"partners-wide"},h={class:"partners-post-gallery"};function m(g,e,_,u,k,f){const l=r("PartnerPostImage"),s=r("PartnerChannelCta");return o(),d("div",null,[e[0]||(e[0]=a('<h1 id="fear-amp-greed" tabindex="-1">Fear &amp; Greed <a class="header-anchor" href="#fear-amp-greed" aria-label="Permalink to &quot;Fear &amp;amp; Greed&quot;">​</a></h1><p>Уровень публикуют все. Уровень сам по себе — наименее полезная половина показателя.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="https://t.me/TickerForgeBot?start=src_channel_fear_greed" rel="nofollow">Открыть карточку Fear &amp; Greed</a><a class="partners-button partners-button--secondary" href="#publish">Публиковать в своём канале</a></div><p class="partners-locale-switch"><a href="/market-intelligence/fear-and-greed" hreflang="en">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a> · <a href="/ru/market-intelligence/market-stress">Рыночный стресс</a> · <a href="/ru/market-intelligence/market-regime">Рыночный режим</a></p><h2 id="answers" tabindex="-1">На какой вопрос отвечает <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;На какой вопрос отвечает {#answers}&quot;">​</a></h2><p><strong>«Настроения восстанавливаются или всё ещё ухудшаются?»</strong></p><p>Значение 30, до которого дошли сверху от 60, и значение 30, до которого дошли снизу от 10, — противоположные ситуации. Печатаются они одинаково. Любая лента, перепечатывающая «Fear &amp; Greed: 30», отдаёт читателю цифру, с которой ничего нельзя сделать без выброшенной половины.</p><h2 id="why" tabindex="-1">Чем это чтение отличается <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Чем это чтение отличается {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Направление считается, а не прикидывается на глаз.</strong> TickerForge прогоняет трендовую логику по самому индексу настроений — скользящие средние и относительную силу по ряду — и публикует, куда он идёт, рядом с тем, где он находится.</li><li><strong>Картинка несёт направление, текст несёт уровень.</strong> Это сделано намеренно: направление — та часть, которой больше нигде нет, поэтому именно она должна пережить пролистывание ленты.</li><li><strong>У разворотов свой алерт.</strong> День, когда направление настроений развернулось, — это другое событие, чем день, когда оно просто продолжилось. И публикуется оно отдельно.</li><li><strong>Это одна строка в большей картине.</strong> Настроения сами по себе не стратегия. Их стоит читать вместе с <a href="/ru/market-intelligence/market-regime">рыночным режимом</a> и <a href="/ru/market-intelligence/market-stress">рыночным стрессом</a>: улучшение настроений в Защитном режиме значит не то же, что то же значение в режиме Тренда.</li></ul></div><h2 id="example" tabindex="-1">Как выглядит пост <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Как выглядит пост {#example}&quot;">​</a></h2>',11)),t("div",p,[t("div",h,[n(l,{src:"/partners/examples/fear-and-greed-sample.png",alt:"Пост TickerForge «Fear & Greed»: уровень настроений и шкала с направлением их движения",caption:"Уровень — в тексте, направление — на шкале.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">Как это считается <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Как это считается {#method}&quot;">​</a></h2><p>Индекс настроений ведётся как ряд, а направление выводится из этого ряда той же трендовой логикой, что и в остальных чтениях TickerForge, — короткая и длинная скользящие плюс относительная сила. Не разностью «сегодня минус вчера», которая переворачивается от шума.</p><h2 id="publish" tabindex="-1">Два способа этим пользоваться <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Два способа этим пользоваться {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Читать.</strong> Ежедневный пост выходит в публичном канале TickerForge; карточка с текущим уровнем и направлением — в боте.</li><li><strong>Публиковать.</strong> Fear &amp; Greed доступен для партнёрских пилотов — напишите на странице <a href="/ru/partners/market-news">рыночных новостей</a>, что это нужный вашему каналу формат: мы приоритизируем по тому, что партнёры реально просят.</li></ul></div>',4)),n(s),e[2]||(e[2]=a('<p>Настроения — это контекст, а не сигнал. Испуганный рынок не становится автоматически возможностью для покупки, а жадный — вершиной. TickerForge — образовательное ПО для поддержки решений, не инвестиционная рекомендация.</p><h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a></li><li><a href="/ru/market-intelligence/market-regime">Рыночный режим</a></li><li><a href="/ru/market-intelligence/market-stress">Рыночный стресс</a></li><li><a href="/ru/partners/market-news">Партнёрская программа по рыночным новостям</a></li></ul>',3))])}const P=i(c,[["render",m]]);export{b as __pageData,P as default};
